    "id": 40,
    "slug": "three-a-m-french-nightlife-pov-399523",
    "title": "Three A.M. French Nightlife POV",
    "category": "Social",
    "rawCategory": "documentary",
    "useCase": "Text prompt",
    "duration": 30,
